<?php

/* @autogenerated */
declare(strict_types=1);

use PHPUnit\Framework\TestCase;
use Civi\Lughauth\Shared\Exception\ConstraintException;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\TrustedClientAllowedAudiencesVO;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\TrustedClientAllowedAudiencesItem;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\TrustedClientAllowedAudiencesUidVO;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\TrustedClientAllowedAudiencesListRef;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\TrustedClientAllowedAudiencesAudienceVO;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\TrustedClientAllowedAudiencesVersionVO;

final class TrustedClientAllowedAudiencesVOUnitTest extends TestCase
{
    public function test_asignation_keep_value(): void
    {
        $value = new TrustedClientAllowedAudiencesListRef(new TrustedClientAllowedAudiencesItem(
            TrustedClientAllowedAudiencesUidVO::from('one'),
            TrustedClientAllowedAudiencesAudienceVO::from('one'),
            TrustedClientAllowedAudiencesVersionVO::from(1)
        ));
        $ref = TrustedClientAllowedAudiencesVO::from($value);
        $this->assertEquals(new TrustedClientAllowedAudiencesListRef(new TrustedClientAllowedAudiencesItem(
            TrustedClientAllowedAudiencesUidVO::from('one'),
            TrustedClientAllowedAudiencesAudienceVO::from('one'),
            TrustedClientAllowedAudiencesVersionVO::from(1)
        )), $ref->value());
        $this->assertTrue(!!$ref->find('one'));
        $this->assertTrue(!$ref->find('other'));
        $current = new TrustedClientAllowedAudiencesItem(
            TrustedClientAllowedAudiencesUidVO::from('one'),
            null,
            null,
        );
        $cloned = TrustedClientAllowedAudiencesVO::from([$current]);
        $clonedFilled = $cloned->getWithDefaults($ref);
        $clonedValue = $cloned->value();
        $clonedFilledValue = $clonedFilled->value();
        $this->assertNull($clonedValue->current()->getAudience());
        $this->assertEquals('one', $clonedFilledValue->current()->getAudience());
        $this->assertNull($clonedValue->current()->getVersion());
        $this->assertEquals(1, $clonedFilledValue->current()->getVersion());
        $other = TrustedClientAllowedAudiencesVO::tryFrom($ref, new ConstraintFailList());
        $this->assertSame($other, $ref);
        $more = TrustedClientAllowedAudiencesVO::from($ref);
        $this->assertSame($more, $ref);
    }
    public function test_asignation_invalid_type(): void
    {
        $errors = new ConstraintFailList();
        $other = TrustedClientAllowedAudiencesVO::tryFrom('1', $errors);
        $this->assertNull($other);
        $this->assertTrue($errors->hasErrors());
    }
    public function test_optimist_asignation_invalid_type(): void
    {
        $this->expectException(ConstraintException::class);
        $method = new ReflectionMethod(TrustedClientAllowedAudiencesVO::class, 'fromUnsafe');
        $method->invoke(null, "bad");
    }
    public function test_equals(): void
    {
        $one = TrustedClientAllowedAudiencesVO::from(new TrustedClientAllowedAudiencesListRef(new TrustedClientAllowedAudiencesItem(
            TrustedClientAllowedAudiencesUidVO::from('one'),
            TrustedClientAllowedAudiencesAudienceVO::from('one'),
            TrustedClientAllowedAudiencesVersionVO::from(1)
        )));
        $same = TrustedClientAllowedAudiencesVO::from(new TrustedClientAllowedAudiencesListRef(new TrustedClientAllowedAudiencesItem(
            TrustedClientAllowedAudiencesUidVO::from('one'),
            TrustedClientAllowedAudiencesAudienceVO::from('one'),
            TrustedClientAllowedAudiencesVersionVO::from(1)
        )));
        $other = TrustedClientAllowedAudiencesVO::from(new TrustedClientAllowedAudiencesListRef(new TrustedClientAllowedAudiencesItem(
            TrustedClientAllowedAudiencesUidVO::from('other'),
            TrustedClientAllowedAudiencesAudienceVO::from('other'),
            TrustedClientAllowedAudiencesVersionVO::from(2)
        )));
        $withEmpty = $one->equals(null);
        $withSame = $one->equals($same);
        $withOther = $one->equals($other);

        $this->assertFalse($withEmpty);
        $this->assertTrue($withSame);
        $this->assertFalse($withOther);
    }
    public function test_build_empty(): void
    {
        $errors = new ConstraintFailList();
        $temp = TrustedClientAllowedAudiencesVO::tryFrom([], $errors);
        $this->assertFalse($temp->value()->valid());
        $temp = TrustedClientAllowedAudiencesVO::tryFrom(null, $errors);
        $this->assertNull($temp->value());
    }
}
